static class V121Checks {
 static T F<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static Action<bool,string> Logger(string path,List<string> lines){return (ok,s)=>{lines.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(path,lines.ToArray());if(!ok)throw new Exception(s);};}
 static void Isolated(string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"v121-state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);}
 public static void DownloadConnection(string path){Isolated(path);try{UpdateService.Check(true).GetAwaiter().GetResult();var release=UpdateService.Latest;if(release==null)throw new Exception(UpdateService.Status);string file=UpdateService.Download(release,null,CancellationToken.None).GetAwaiter().GetResult();bool guarded=false;try{UpdateService.PrepareAndRestart(file,release);}catch(InvalidOperationException){guarded=true;}if(!guarded)throw new Exception("Downgrade guard failed");File.WriteAllText(path,"PASS Actual official Release API and HTTPS asset download\nPASS SHA-256 + byte size + embedded EXE version verified\nPASS Older version cannot enter installation\n"+release.Page+"\nSHA256 "+UpdateService.HashFile(file));}catch(Exception ex){File.WriteAllText(path,"FAIL "+ex);Environment.ExitCode=1;}}
 public static void Connection(string path){Isolated(path);UpdateService.Check(true).GetAwaiter().GetResult();File.WriteAllText(path,(UpdateService.Latest!=null?"PASS ":"FAIL ")+UpdateService.Status+"\n"+(UpdateService.Latest==null?"":UpdateService.Latest.Page));if(UpdateService.Latest==null)Environment.ExitCode=1;}
 public static void Run(string path){Isolated(path);var lines=new List<string>();var check=Logger(path,lines);try{var levels=ChallengeBank.Levels;check(levels.Count==50&&levels.Select(l=>l.Number).SequenceEqual(Enumerable.Range(1,50)),"50 contiguous levels");check(levels.First().Seconds==480&&levels.Last().Seconds==1800&&levels.Zip(levels.Skip(1),(a,b)=>a.Seconds<=b.Seconds).All(x=>x),"8-30 minute nondecreasing limits");check(levels.All(l=>l.Learning.Length>350&&l.Learning.Contains("分步提示")&&l.Learning.Contains("常见错误")),"Every level contains detailed learning, steps and edge-case advice");check(levels.First().Problem.Title.Contains("数位和")&&!levels.Any(l=>l.Problem.Title.Contains("能量管网")||l.Problem.Title.Contains("强连通")||l.Problem.Title.Contains("远征路线")),"Entry matches basic loop practice; specialized hard topics removed");
  foreach(int size in AppSettings.FontSizes){AppSettings.SetFont(size);check(AppSettings.EditorFont==size,"Font preference "+size);}AppSettings.SetFont(16);AppSettings.SetAutoCheck(false);check(!AppSettings.AutoCheck,"Auto-check preference saved");AppSettings.SetAutoCheck(true);check(AppSettings.AutoCheck,"Auto-check can be re-enabled");
  Version v;check(UpdateService.TryVersion("ver1.2.10",out v)&&v>UpdateService.Current,"Numeric version comparison 1.2.10 > 1.2.1");foreach(string tag in new[]{"ver1.2.2-beta","1.2.x","1.2.1/evil","9999999999999.2.1"})check(!UpdateService.TryVersion(tag,out v),"Reject malformed/preview tag "+tag);
  string hash=new string('a',64),url=UpdateService.Repo+"/releases/download/ver1.2.2/Feng_C_Practice_ver1.2.2.exe";var serializer=new JavaScriptSerializer();Func<string,string,bool,string> data=(tag,download,preview)=>serializer.Serialize(new{tag_name=tag,draft=false,prerelease=preview,body="更新说明",assets=new[]{new{name="Feng_C_Practice_ver1.2.2.exe",state="uploaded",size=4096,browser_download_url=download,digest="sha256:"+hash}}});var release=UpdateService.Parse(data("ver1.2.2",url,false));check(release.Newer&&release.CanInstall&&release.Sha256==hash,"New release selects official EXE and digest");check(!UpdateService.Parse(data("ver1.1.1",url,false)).Newer,"Older GitHub release never downgrades local version");check(!UpdateService.Parse(data("ver1.2.2","https://evil.example/app.exe",false)).CanInstall,"Foreign binary URL rejected");bool rejected=false;try{UpdateService.Parse(data("ver1.2.2",url,true));}catch{rejected=true;}check(rejected,"Pre-release ignored");foreach(string bad in new[]{"http://github.com/app.exe","https://github.com.evil.example/app.exe","https://user@github.com/app.exe","file:///C:/test.exe"})check(!UpdateService.AllowedUri(new Uri(bad)),"Unsafe transport rejected: "+bad);check(UpdateService.ParseChecksum(hash+"  Feng.exe\n","Feng.exe")==hash,"Checksum exact asset name parsed");rejected=false;try{UpdateService.ParseChecksum(hash+"  Other.exe","Feng.exe");}catch{rejected=true;}check(rejected,"Checksum cannot match another asset");
  string own=Assembly.GetExecutingAssembly().Location;UpdateService.Verify(own,UpdateService.HashFile(own),new FileInfo(own).Length,UpdateService.Current);check(true,"Local EXE hash, PE header and version verification");rejected=false;try{UpdateService.Verify(own,hash,new FileInfo(own).Length,UpdateService.Current);}catch{rejected=true;}check(rejected,"Tampered hash rejected before install");rejected=false;try{UpdateService.Verify(own,UpdateService.HashFile(own),new FileInfo(own).Length,new Version(1,2,2,0));}catch{rejected=true;}check(rejected,"Mismatched executable version rejected");
  var copy=typeof(UpdateService).GetMethod("Copy",BindingFlags.Static|BindingFlags.NonPublic);rejected=false;try{((Task)copy.Invoke(null,new object[]{new MemoryStream(new byte[3]),new MemoryStream(),10L,5L,null,CancellationToken.None})).GetAwaiter().GetResult();}catch{rejected=true;}check(rejected,"Truncated download rejected");rejected=false;try{((Task)copy.Invoke(null,new object[]{new MemoryStream(new byte[11]),new MemoryStream(),10L,-1L,null,CancellationToken.None})).GetAwaiter().GetResult();}catch{rejected=true;}check(rejected,"Oversized download rejected");
  var state=new ChallengeProgress(Engine.DataRoot);check(state.Root.EndsWith("challenge-ver1.2.1")&&state.Unlocked==1,"New curriculum has separate progress; old challenge scores not reused");state.Begin(1,levels[0].Seconds);check((state.Deadline-DateTime.UtcNow).TotalSeconds>470,"New attempt uses 8 minutes");state.End();
  int cases=0;foreach(var l in levels){foreach(int seed in new[]{20261022,12150}){var ev=Engine.Judge(l.Problem,l.Problem.Reference,seed,CancellationToken.None,(a,b)=>{});if(!ev.Compiled||ev.Cases.Any(c=>!c.Passed))File.WriteAllText(path+".failure.txt",Engine.Report(ev));check(ev.Compiled&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Passed),"Reference level "+l.Number+" seed "+seed+" (28 cases)");cases+=ev.Cases.Count;}if(l.Number%5==0)Console.WriteLine("Validated "+l.Number+" / 50");}
  var wrong=Engine.Judge(levels[0].Problem,"#include <stdio.h>\nint main(void){puts(\"-999\");return 0;}",121,CancellationToken.None,(a,b)=>{});check(!ChallengeProgress.Qualifies(wrong)&&wrong.Cases.Any(c=>!c.Passed),"Wrong submission cannot unlock challenge");string why;check(!Engine.Match("0000","0",out why,true),"Text leading zeroes preserved");foreach(int id in new[]{1,38,58,88}){var p=Bank.All().First(x=>x.Id==id);var ev=Engine.Judge(p,p.Reference,121,CancellationToken.None,(a,b)=>{});check(ev.Compiled&&ev.Cases.All(c=>c.Passed),"Ordinary practice regression "+id);}lines.Add("ALL VER1.2.1 CORE CHECKS PASSED · "+cases+" challenge cases + 112 ordinary cases");File.WriteAllLines(path,lines.ToArray());}catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(path,lines.ToArray());Environment.ExitCode=1;}}
 public static void RunUI(Application app,string path){Isolated(path);var lines=new List<string>();var check=Logger(path,lines);var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{await Transitions.WhenReady(main);var edit=F<CodeEditor>(main,"editor");var game=new ChallengeWindow(true){Owner=main};game.Show();await Transitions.WhenReady(game);var map=F<ConstellationMap>(game,"map");check(map.SelectedNumber==1&&map.IsEnabled,"Top star map selects first unlocked node");game.StartForCheck();check(map.IsEnabled&&map.SelectionLocked,"Countdown locks selection without disabling the dark map");check(F<TextBlock>(game,"clock").Text.StartsWith("08:"),"Countdown begins at eight minutes");game.Select(2);check(map.SelectedNumber==1,"Locked next level cannot be selected");game.Editor.Text="int main(void){return 0;}";game.Editor.Input.SelectedText="\n";check(game.Editor.CanUndo,"Editor history stays available during challenge");game.Editor.Undo();game.Editor.Redo();
  var settings=new SettingsWindow(true,true){Owner=game};settings.Show();await Transitions.WhenReady(settings);check(Transitions.Duration(settings)==500&&Transitions.IsComplete(settings),"Settings popup completes smooth 500ms fade");F<List<Button>>(settings,"fontChoices").First(b=>(int)b.Tag==22).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(edit.Input.FontSize==22&&game.Editor.Input.FontSize==22,"Settings font applies to both editors without scaling");Theme.Capture((FrameworkElement)settings.Content,Path.Combine(Path.GetDirectoryName(path),"设置-暗色.png"),144);settings.Close();game.StartForCheck();check(!game.IsAttemptRunning&&map.IsEnabled&&!map.SelectionLocked,"Ending attempt restores selection and keeps dark appearance");
  string code="#include <stdio.h>\nint main(void)\n{\n    int value = 12;\n    printf(\"%d\", value);\n    return 0;\n}\n";edit.Text=code;game.Editor.Text=code;int hits=0;foreach(double dpi in new[]{96.0,144.0,192.0}){double w=2560*96/dpi,h=1600*96/dpi;main.PreviewSize(w,h);game.PreviewSize(w,h);foreach(int size in AppSettings.FontSizes){AppSettings.SetFont(size);main.UpdateLayout();game.UpdateLayout();await Task.Delay(40);foreach(var editor in new[]{edit,game.Editor}){editor.Input.ScrollToHome();editor.RefreshView();var input=editor.Input;for(int i=0;i<code.Length-1;i++){if(code[i]=='\n'||code[i+1]=='\n')continue;var a=input.CharacterRect(i);var b=input.CharacterRect(i+1);if(b.X<=a.X)continue;var p=new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5);if(input.Hit(p)!=i)throw new Exception("Cursor mismatch "+dpi+"dpi / "+size+" / "+i);hits++;}}check(true,"Editor hit geometry both modes "+dpi+"dpi / font "+size);}
   check(game.Editor.ActualHeight>180&&game.Editor.ActualWidth>550,"Dark workspace remains usable at "+dpi+"dpi");Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"暗域-"+dpi+"dpi.png"),dpi);}
  AppSettings.SetFont(16);main.PreviewSize(1600,1000);game.PreviewSize(1600,1000);game.Editor.Text="";for(int i=1;i<=49;i++)game.Progress.Scores[i]=100;F<ChallengeLevel>(game,"level");typeof(ChallengeWindow).GetMethod("RefreshMap",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,null);game.Select(50);await Task.Delay(100);game.UpdateLayout();check(map.SelectedNumber==50&&map.Scroller.HorizontalOffset>1000,"50th star scrolls into view and can be reached");Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"终章星轨.png"),153.6);game.Select(1);await Task.Delay(450);game.Progress.Scores.Clear();typeof(ChallengeWindow).GetMethod("RefreshMap",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,null);game.PreviewSize(1600,1000);Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"暗域-星座预览.png"),153.6);game.Close();
  var light=new SettingsWindow(false,true){Owner=main};light.Show();await Transitions.WhenReady(light);Theme.Capture((FrameworkElement)light.Content,Path.Combine(Path.GetDirectoryName(path),"设置-浅色.png"),144);light.Close();main.PreviewSize(1600,1000);Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"主界面-2.5K.png"),153.6);lines.Add("ALL VER1.2.1 UI CHECKS PASSED · "+hits+" character hit positions");File.WriteAllLines(path,lines.ToArray());main.Close();}catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(path,lines.ToArray());app.Shutdown(1);}};app.Run(main);}
}
